(() => {
  'use strict';
  const data = window.SHOWDOWN_BOOK;
  const research = window.CHRONICLE_RESEARCH;
  if (!data || !data.chapters.length) return;
  const $ = selector => document.querySelector(selector);
  const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt = value => Number(value).toLocaleString('en-US');
  const pad = value => String(value).padStart(3,'0');
  const part = id => data.parts.find(p=>p.id===id);
  const chapter = id => data.chapters.find(c=>c.id===id);
  const main = $('#book-main');
  const storage = {
    get(key,fallback){try{return JSON.parse(localStorage.getItem(`cms-chronicle-${key}`)) ?? fallback;}catch{return fallback;}},
    set(key,value){try{localStorage.setItem(`cms-chronicle-${key}`,JSON.stringify(value));}catch{}}
  };
  let visited = new Set(storage.get('visited',[]));
  let saved = new Set(storage.get('saved',[]));
  let activeChapter = null;
  let toastTimer;
  const external = (url,label,cls='source-note') => `<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener">${esc(label)} ↗</a>`;
  const table = (columns,rows) => `<div class="table-scroll" tabindex="0" role="region" aria-label="${esc(columns.join(', '))}"><table class="book-table"><thead><tr>${columns.map(c=>`<th scope="col">${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((c,i)=>i===0?`<th scope="row">${esc(c)}</th>`:`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const heading = (eyebrow,title,dek='') => `<p class="eyebrow">${esc(eyebrow)}</p><h1>${title}</h1>${dek?`<p class="book-intro">${esc(dek)}</p>`:''}`;
  const scope = text => `<p class="book-scope">${esc(text)}</p>`;
  const stateChips = states => `<div class="state-chips">${Object.entries(states).map(([key,value])=>`<span><b>${value}</b>${esc(key)}</span>`).join('')}</div>`;
  function toast(text){$('#book-toast').textContent=text;$('#book-toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#book-toast').classList.remove('show'),2200);}
  function blocks(ch){return ch.blocks.map(b=>{
    if(b.type==='h2')return `<h2>${esc(b.text)}</h2>`;
    if(b.type==='list')return `<ul>${b.items.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`;
    if(b.type==='table')return table(b.columns,b.rows);
    if(b.type==='callout')return `<aside class="book-callout"><strong>${esc(b.label)}</strong><p>${esc(b.text)}</p></aside>`;
    return `<p>${esc(b.text)}</p>`;
  }).join('');}
  function sourceNotes(sources){return sources.map(s=>`<a class="source-note" href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.label)} ↗<small>${esc(s.branch)} · ${esc(s.ref.slice(0,8))}<br>${esc(s.path)}</small></a>`).join('');}
  function chapterEntry(c){return `<a class="chapter-entry" href="#read/${esc(c.id)}"><span class="entry-number">${pad(c.number)}</span><span><b>${esc(c.title)}</b><small>${esc(c.dek)}</small></span>${visited.has(c.id)?'<span class="visited-dot" aria-label="Visited">●</span>':''}</a>`;}
  function readingState(){ $('#reading-state').textContent=`${visited.size} of ${data.chapters.length} chapters visited · ${saved.size} saved`; }
  function closeDrawer(){document.body.classList.remove('drawer-open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#drawer-backdrop').hidden=true;}
  function markNav(route,partId=''){
    document.querySelectorAll('.book-primary a').forEach(a=>a.classList.toggle('current',a.getAttribute('href')===`#${route}`));
    document.querySelectorAll('#volume-nav a').forEach(a=>a.classList.toggle('current',a.dataset.part===partId));
  }
  function contents(onlyPart=''){
    activeChapter=null;
    const groups=data.parts.filter(p=>!onlyPart||p.id===onlyPart);
    const last=chapter(storage.get('last',''));
    main.innerHTML=onlyPart?heading('THE COMPLETE CHRONICLE / VOLUME',esc(groups[0]?.title||'Contents'),groups[0]?.dek||''): `<section class="book-cover"><img src="assets/home.webp" alt="Daniel and Nik in the project’s original gold-lit stadium scene" width="1672" height="941"><p class="eyebrow">THE PROJECT, IN ITS OWN RECORDS</p><h1>A rivalry.<br>A world.<br><em>A system.</em></h1><p>The complete story of Career Mode Showdown—from two friends and a score sheet to cinematic scenes, shared protocols, factories and an evolving way to build.</p><div class="cover-footer"><a class="book-button gold" href="#read/${esc(data.chapters[0].id)}">Open the book →</a>${last?`<a class="book-button" href="#read/${esc(last.id)}">Continue chapter ${pad(last.number)} →</a>`:''}<small>CHRONICLE EDITION 11 · SIXTEEN VOLUMES<br>BUILDING 2.0 · UPDATED 1 NOVEMBER 2026</small></div></section><div class="book-counts"><div><strong>${data.chapters.length}</strong><span>EDITORIAL CHAPTERS</span></div><div><strong>${fmt(data.wordCount)}</strong><span>WORDS IN THE BOOK</span></div><div><strong>${data.jobs.length}</strong><span>HISTORICAL STATUS RECORDS</span></div><div><strong>${data.sources.length}</strong><span>CITED SOURCE URLS</span></div></div><aside class="latest-checkpoint"><strong>r86</strong><div><span class="eyebrow">1 NOVEMBER / BUILDING 2.0</span><p>R86 is released. Eight new chapters cover R87 staging, teams, Prime Pack, presentation, hardening and STORY. Earlier research retains its snapshot dates.</p><a href="#volume/next-chapter">Read Volume 16 →</a></div></aside><p class="eyebrow">CHOOSE A READING PATH</p><div class="reading-paths"><a class="reading-path" href="#volume/origins"><small>THE HUMAN STORY</small><strong>How the idea grew.</strong><p>Owner decisions, early repairs, and the evolution from local play to a shared rivalry.</p><span>Begin with the origin →</span></a><a class="reading-path" href="#latest/models-current"><small>THE FACTORY STORY</small><strong>What the model evidence supports.</strong><p>Jobs, models, reviews, handoffs, and the lessons behind the worker routing.</p><span>Explore workers & evaluations →</span></a><a class="reading-path" href="#volume/pos20"><small>THE SYSTEM STORY</small><strong>How trust gets built.</strong><p>Decision rules, proof routing, recovery, seven Gate lanes, and physical acceptance.</p><span>Read the operating system →</span></a></div>`;
    main.insertAdjacentHTML('beforeend',`<div class="book-actions"><a class="book-button" href="#search">Search the full book ⌕</a><a class="book-button" href="#atlas">Open research atlas ↗</a><button class="book-button" data-action="print-all">Print the complete book</button></div><div class="volume-shelf">${groups.map((p)=>{const cs=data.chapters.filter(c=>c.part===p.id);return `<section class="volume" id="volume-${esc(p.id)}"><div class="volume-number">${String(data.parts.indexOf(p)+1).padStart(2,'0')}</div><div><div class="volume-head"><div><h2>${esc(p.title)}</h2><p>${esc(p.dek)}</p></div><span>${cs.length} CHAPTERS</span></div><div class="chapter-shelf">${cs.map(chapterEntry).join('')}</div></div></section>`;}).join('')}</div>${scope(data.method)}${scope('Chapter numbers identify editorial reading pages, not a claim that every browser or print layout has an identical page count. Job dossiers, release records and commits are additional research material, counted separately.')}`);
    markNav('contents',onlyPart);readingState();
  }
  function readChapter(id){
    const ch=chapter(id);if(!ch){notFound();return;}
    activeChapter=ch;visited.add(ch.id);storage.set('visited',[...visited]);storage.set('last',ch.id);
    const p=part(ch.part);const index=data.chapters.indexOf(ch);const prev=data.chapters[index-1];const next=data.chapters[index+1];
    document.title=`${ch.title} — The Complete Chronicle`;
    main.innerHTML=`<div class="chapter-kicker"><a href="#volume/${esc(ch.part)}">← ${esc(p.title)}</a><span>CHAPTER ${pad(ch.number)} / ${data.chapters.length} · ${ch.minutes} MIN READ</span></div>${heading(`VOLUME ${String(data.parts.indexOf(p)+1).padStart(2,'0')} / ${p.title}`,esc(ch.title),ch.dek)}<div class="book-actions"><button class="book-button" data-action="save" aria-pressed="${saved.has(ch.id)}">${saved.has(ch.id)?'♥ Saved':'♡ Save chapter'}</button><button class="book-button" data-action="copy">Copy chapter link ↗</button><button class="book-button" data-action="print">Print chapter</button></div><div class="chapter-banner"><img src="assets/${esc(p.image)}" alt="Original Career Mode Showdown repository artwork" width="1672" height="941"><span>ORIGINAL REPOSITORY SCENE PLATE · EDITORIAL ILLUSTRATION</span></div><div class="reader-layout"><article class="chapter-prose">${blocks(ch)}<div class="chapter-footer">${prev?`<a href="#read/${esc(prev.id)}"><small>← PREVIOUS CHAPTER ${pad(prev.number)}</small>${esc(prev.title)}</a>`:'<span></span>'}${next?`<a href="#read/${esc(next.id)}"><small>NEXT CHAPTER ${pad(next.number)} →</small>${esc(next.title)}</a>`:'<a href="#contents"><small>RETURN TO THE BOOK →</small>Explore another volume</a>'}</div></article><aside class="chapter-aside"><p class="eyebrow">THE EVIDENCE</p><p>Editorial explanation grounded in the pinned files below. Historical observations keep their original scope.</p>${sourceNotes(ch.sources)}<div class="tag-row">${ch.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div><a class="source-note" href="#atlas">Explore the research atlas →</a></aside></div>`;
    if(ch.part!=='current')main.insertAdjacentHTML('afterbegin','<aside class="historical-snapshot">Historical chapter, grounded in its original source dates. <a href="#volume/current">Read the Mega Factory era and current changes →</a></aside>');
    markNav('contents',ch.part);readingState();
  }
  function filteredJobs(team,state,q){return data.jobs.filter(j=>(team==='All'||j.team===team)&&(state==='All'||j.state===state)&&`${j.number} ${j.title} ${j.worker} ${j.metadata.phase||''} ${j.metadata.type||''} ${j.statusExcerpt} ${j.briefExcerpt}`.toLowerCase().includes(q.toLowerCase().trim()));}
  function archive(kind,team='All'){
    activeChapter=null;const isJobs=kind==='jobs';const records=isJobs?data.jobs:data.releases;let page=0;const size=18;
    main.innerHTML=heading(isJobs?'FACTORY RESEARCH / 296 STATUS FILES':'THE RELEASE LIBRARY / SOURCE RECORDS',isJobs?'Every job has<br><span>a paper trail.</span>':'The release<br><span>record collection.</span>',isJobs?'Search the recorded work by team, state, title or worker. Open a dossier to see the brief, status, dependency fields and original evidence.':'Ninety-three root release documents, with their runtime identities, section outlines and pinned source links. Some records preserve pre-merge states.')+`<div class="archive-controls"><div class="wide-control"><label for="archive-query">SEARCH ${isJobs?'JOBS & WORKERS':'RELEASES'}</label><input id="archive-query" type="search" placeholder="${isJobs?'e.g. phone, 1010, trophy, Sol':'e.g. r51, restore, offline, Version 2.0'}"></div>${isJobs?'<div><label for="archive-team">TEAM</label><select id="archive-team"><option>All</option><option>G</option><option>V</option></select></div><div><label for="archive-state">RECORDED STATE</label><select id="archive-state"><option>All</option>'+[...new Set(data.jobs.map(j=>j.state))].map(s=>`<option>${esc(s)}</option>`).join('')+'</select></div>':''}</div><p class="book-scope" id="archive-count" role="status"></p><div class="archive-list" id="archive-list"></div><div class="archive-pagination"><button id="archive-prev" class="book-button">← Previous</button><span id="archive-page"></span><button id="archive-next" class="book-button">Next →</button></div>${scope(isJobs?'DONE, MERGED and retained intake markers report what the source files say. They do not establish that every item shipped or passed a fresh independent review. The job brief’s assigned worker and the status file’s reported chat can differ.':'Dates here are each file’s last recorded commit date on pinned main, not automatically the release or deployment date. A release document can be historical evidence without representing a separate production deployment.')}`;
    function render(){const q=$('#archive-query').value.toLowerCase().trim();const rows=isJobs?filteredJobs($('#archive-team').value,$('#archive-state').value,q):records.filter(r=>`${r.title} ${r.file} ${r.runtime} ${r.sections.join(' ')}`.toLowerCase().includes(q));const pages=Math.max(1,Math.ceil(rows.length/size));page=Math.min(page,pages-1);$('#archive-count').textContent=`${rows.length} of ${records.length} records`;$('#archive-list').innerHTML=rows.slice(page*size,(page+1)*size).map(r=>isJobs?`<a class="archive-row" href="#job/${esc(r.id)}"><span class="record-id">${r.team}·${esc(r.number)}</span><span><strong>${esc(r.title)}</strong><small>${esc(r.worker)}<br>${esc(r.metadata.phase||'')} · Step ${esc(r.step||'not recorded')}</small></span><span class="record-state">${esc(r.rawState)}</span></a>`:`<a class="archive-row" href="#release/${esc(r.id)}"><span class="record-id">${esc(r.runtime.replace('1.9.1-','')||r.file.match(/V([\d.]+)/)?.[1]||'DOC')}</span><span><strong>${esc(r.title)}</strong><small>${esc(r.date)} · last source commit<br>${esc(r.recordedState||'Read the original record for its status')}</small></span><span class="record-state">OPEN ↗</span></a>`).join('')||'<div class="book-empty">No matching records. Try another search or filter.</div>';$('#archive-page').textContent=`${page+1} / ${pages}`;$('#archive-prev').disabled=page===0;$('#archive-next').disabled=page===pages-1;}
    $('#archive-query').addEventListener('input',()=>{page=0;render();});if(isJobs){$('#archive-team').addEventListener('change',()=>{page=0;render();});$('#archive-state').addEventListener('change',()=>{page=0;render();});}$('#archive-prev').addEventListener('click',()=>{page--;render();});$('#archive-next').addEventListener('click',()=>{page++;render();});if(isJobs&&['G','V'].includes(team))$('#archive-team').value=team;render();markNav(kind);
  }
  function record(kind,id){
    activeChapter=null;const isJob=kind==='job';const r=(isJob?data.jobs:data.releases).find(x=>x.id===id);if(!r){notFound();return;}
    const facts=isJob?[['Team',`Team ${r.team}`],['State in the file',r.rawState],['Progress step',r.step||'Not recorded'],['Updated line',r.updated||'Not recorded'],['Reported worker/chat',r.worker],['Assigned worker in board',r.metadata.worker||'Not recorded'],['Lane',r.metadata.lane||'Not recorded'],['Phase / kind',`${r.metadata.phase||'Not recorded'} / ${r.metadata.type||'Not recorded'}`],['Retained intake marker',r.intake||'No marker recorded'],['Dependencies',(r.metadata.depends_on||[]).join(', ')||'None in board metadata']]:[['Runtime identity',r.runtime||'Not recorded in that field'],['Recorded status',r.recordedState||'Inspect source'],['Last source commit',r.date],['File',r.file]];
    main.innerHTML=`<div class="chapter-kicker"><a href="#${isJob?'jobs':'releases'}">← ${isJob?'Job archive':'Release library'}</a><span>${isJob?`TEAM ${r.team} / JOB ${esc(r.number)}`:'SOURCE RECORD'}</span></div>${heading(isJob?'FACTORY DOSSIER':'RELEASE DOSSIER',esc(r.title))}<dl class="record-facts">${facts.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${isJob?[['JOB BRIEF / SHORT SOURCE EXCERPT',r.briefExcerpt],['STATUS NOTES / SHORT SOURCE EXCERPT',r.statusExcerpt]].filter(x=>x[1]).map(([label,text])=>`<div class="record-excerpt"><span class="eyebrow">${label}</span><p>${esc(text)}</p></div>`).join(''):`<div class="record-excerpt"><span class="eyebrow">SHORT SOURCE EXCERPT</span><p>${esc(r.excerpt||'Open the record for its complete evidence.')}</p></div><h2>Inside the record</h2><ul>${r.sections.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`}<h2>Open the evidence</h2><div class="record-source-links">${sourceNotes(isJob?r.sources:[r.source])}${isJob?r.prs.map(url=>external(url,`Linked PR #${url.split('/').pop()}`)).join(''):''}</div>${scope(isJob?'These factual fields and bounded excerpts are a source dossier, not a new verdict on the job. A retained PASS line can belong to an earlier intake, and a DONE label can precede integration into production. Read the linked notes for rework, exceptions and evidence limits.':'This document’s original state is preserved. Its runtime, source integration, public deployment and physical acceptance can be different milestones. The source record is the authority for what it actually claims.')}`;markNav(isJob?'jobs':'releases');
  }
  function timeline(){
    activeChapter=null;let page=0;const size=24;
    main.innerHTML=heading('THE INTEGRATION SPINE / FIRST-PARENT MAIN HISTORY','Seven hundred<br><span>eighty-seven commits.</span>','Search every recorded step along main’s first-parent history. This includes maintenance, documentation, release and integration commits.')+`<div class="archive-controls"><div class="wide-control"><label for="commit-query">SEARCH SUBJECTS OR SHA</label><input id="commit-query" type="search" placeholder="e.g. Candidate C, pairing, r62, factory"></div><div><label for="commit-month">MONTH</label><select id="commit-month"><option value="All">All months</option>${research.repository.months.map(m=>`<option value="${m.month}">${m.month}</option>`).join('')}</select></div><div><label for="commit-order">ORDER</label><select id="commit-order"><option value="old">Oldest first</option><option value="new">Newest first</option></select></div></div><p id="commit-count" class="book-scope" role="status"></p><div id="commit-list"></div><div class="archive-pagination"><button class="book-button" id="commit-prev">← Previous</button><span id="commit-page"></span><button class="book-button" id="commit-next">Next →</button></div>${scope('The author timestamp converted to UTC determines each commit’s displayed date and month. First-parent history follows the main integration spine; 3,097 reachable commit objects also include merged branch history. Neither count measures features, hours worked or product quality.')}`;
    function render(){const q=$('#commit-query').value.toLowerCase().trim();let rows=data.history.filter(r=>($('#commit-month').value==='All'||r.date.startsWith($('#commit-month').value))&&`${r.title} ${r.sha}`.toLowerCase().includes(q));if($('#commit-order').value==='new')rows=rows.slice().reverse();const pages=Math.max(1,Math.ceil(rows.length/size));page=Math.min(page,pages-1);$('#commit-count').textContent=`${rows.length} matching commits`;$('#commit-list').innerHTML=rows.slice(page*size,(page+1)*size).map(r=>`<div class="timeline-day"><time datetime="${r.date}">${esc(r.date.slice(5))}</time><div>${external(r.url,r.title,'commit-link')}<small>${esc(r.sha.slice(0,10))} · ${esc(r.date)}</small></div></div>`).join('')||'<div class="book-empty">No commits match.</div>';$('#commit-page').textContent=`${page+1} / ${pages}`;$('#commit-prev').disabled=page===0;$('#commit-next').disabled=page===pages-1;}
    ['commit-query','commit-month','commit-order'].forEach(id=>$('#'+id).addEventListener(id==='commit-query'?'input':'change',()=>{page=0;render();}));$('#commit-prev').addEventListener('click',()=>{page--;render();});$('#commit-next').addEventListener('click',()=>{page++;render();});render();markNav('timeline');
  }

  const statDefinitions = [
    ['stats-worker-mix','Task mix and first-pass outcomes','237','credited assignments','Which kinds of work sit behind the worker comparison?'],
    ['stats-review','First review and final review','76','numerically scored jobs','How do recorded review averages differ at the two endpoints?'],
    ['stats-factories','What the factory records contain','296','status-file dossiers','How are phase and type labels distributed across each factory?'],
    ['stats-weeks','Main integration, week by week','787','first-parent commits','When did commits enter the main integration spine?'],
    ['stats-olympiad','Olympiad runs and finding files','11','numbered hunt areas','Where did the archived investigations concentrate?'],
    ['stats-evidence','The book, volume by volume',String(data.chapters.length),'editorial chapters','How much text and cited evidence sits behind each volume?'],
    ['stats-lineage','Why the factory totals differ','276','board definitions','Which status files have a matching entry on their pinned board?'],
    ['stats-linkage','Can the QA records be joined?','31','distinct finding identifiers','Which finding-to-check relationships are unambiguous?']
  ];
  function statsNav(selected){return `<nav class="stats-jump" aria-label="Statistical views"><a class="stats-home" href="#numbers">All eight views</a>${statDefinitions.map((d,i)=>`<a href="#${d[0]}" ${d[0]===selected?'aria-current="page"':''}>${String(i+1).padStart(2,'0')} ${esc(d[1])}</a>`).join('')}</nav>`;}
  function olympiadLinks(){
    const findings=new Map(),checks=new Map();
    for(const f of data.olympiad.findings){const a=findings.get(f.id)||[];a.push(f);findings.set(f.id,a);}
    for(const c of data.olympiad.checks){const a=checks.get(c.id)||[];a.push(c);checks.set(c.id,a);}
    const rows=data.olympiad.findings.map(f=>{const candidates=checks.get(f.id)||[],ambiguous=(findings.get(f.id)?.length||0)!==1||candidates.length>1;const check=!ambiguous&&candidates.length===1?candidates[0]:null;return {...f,check,candidates,linkState:ambiguous?'ambiguous':check?.result||'unreviewed',linkLabel:ambiguous?'Ambiguous identifier — no check assigned':check?.result?.replaceAll('_',' ')||'No linked check in snapshot'};});
    return {rows,findings,checks,orphanChecks:data.olympiad.checks.filter(c=>!findings.has(c.id))};
  }
  function numbers(){
    activeChapter=null;
    main.innerHTML=heading('THE NUMBERS / EIGHT WAYS INTO THE PROJECT','A clearer view<br><span>of the evidence.</span>','Start with a question. Each view gives the count, its denominator, the source snapshot and the limits of the conclusion.')+`<div class="number-grid">${statDefinitions.map((d,i)=>`<a class="number-card" href="#${d[0]}"><span class="eyebrow">VIEW ${String(i+1).padStart(2,'0')}</span><div class="number-value">${d[2]}<small>${d[3]}</small></div><h2>${esc(d[1])}</h2><p>${esc(d[4])}</p><span class="number-open">Explore the evidence →</span></a>`).join('')}</div><section class="atlas-section"><p class="eyebrow">HOW TO READ THIS EDITION</p><h2>Every total has a boundary.</h2><div class="method-grid"><article><h3>Records and outcomes</h3><p>A job file, a review, a Git commit and a QA claim count different things. Keep their units separate.</p></article><article><h3>Snapshot and timeline</h3><p>Boards are inventories at pinned commits. Commit cadence uses author timestamps converted to UTC. A board snapshot is not a full event log.</p></article><article><h3>Definitions and execution</h3><p>Registered tests, gates and acceptance weights describe the system. They do not establish a fresh pass or earned product acceptance.</p></article></div>${table(['Source snapshot','Author date in UTC','Pinned commit'],Object.entries(data.refs).map(([b,sha])=>[b,data.snapshotDates[b],sha.slice(0,12)]))}<p class="book-scope">Snapshots through 7 October 2026. The pinned main head was authored 5 October in Eastern time, which is 6 October in UTC. Board dates differ. Open the source index for exact immutable links.</p><div class="book-actions"><a href="#atlas" class="book-button">Explore the system atlas →</a><a href="#sources" class="book-button">Inspect pinned sources →</a></div></section>`;
    markNav('numbers');
  }
  function statistics(id){
    const i=statDefinitions.findIndex(d=>d[0]===id);if(i<0){notFound();return;}
    activeChapter=null;const d=statDefinitions[i];document.title=`${d[1]} — Career Mode Showdown Chronicle`;
    main.innerHTML=`<div class="stat-reader">${heading(`THE NUMBERS / VIEW ${String(i+1).padStart(2,'0')} OF ${statDefinitions.length}`,esc(d[1]),d[4])}${expandedStats(id)}<nav class="stat-pagination" aria-label="Previous and next statistical view">${i>0?`<a href="#${statDefinitions[i-1][0]}"><small>PREVIOUS VIEW</small>${esc(statDefinitions[i-1][1])}</a>`:'<a href="#numbers">← All eight views</a>'}${i<statDefinitions.length-1?`<a href="#${statDefinitions[i+1][0]}"><small>NEXT VIEW</small>${esc(statDefinitions[i+1][1])} →</a>`:'<a href="#atlas">Continue to the system atlas →</a>'}</nav></div>`;markNav('numbers');
  }
  function expandedStats(selected=null){
    const repo='https://github.com/nikahanghojjati-oss/fifa17-career-showdown2';
    const source=(branch,path)=>`${repo}/blob/${data.refs[branch]}/${path}`;
    const workerNames=Object.keys(data.workers);
    const kinds=[...new Set(Object.values(data.workers).flatMap(w=>Object.keys(w.by_kind)))].sort((a,b)=>a.localeCompare(b));
    const mixRows=kinds.map(kind=>[kind,...workerNames.map(name=>{const v=data.workers[name].by_kind[kind];return v?`${v[1]} / ${v[0]} · ${(v[1]/v[0]*100).toFixed(1)}%`:'No recorded jobs';}),String(workerNames.reduce((n,name)=>n+(data.workers[name].by_kind[kind]?.[0]||0),0))]);
    const mixTable=table(['Recorded task kind',...workerNames,'Jobs in slice'],mixRows);
    const taskSummary=kinds.map(kind=>{const jobs=workerNames.reduce((n,name)=>n+(data.workers[name].by_kind[kind]?.[0]||0),0),passes=workerNames.reduce((n,name)=>n+(data.workers[name].by_kind[kind]?.[1]||0),0);return {kind,jobs,passes};});
    const taskChart=`<div class="task-summary">${taskSummary.map(t=>`<div class="task-summary-row"><span>${esc(t.kind)}</span><i><em style="width:${t.jobs/237*100}%"></em></i><b>${t.jobs} jobs<small>${t.passes} first passes</small></b></div>`).join('')}</div><p class="book-scope">Bars show each task kind’s share of all 237 credited assignments. First-pass counts are recorded outcomes within those assignments.</p>`;

    const totalJobs=workerNames.reduce((n,name)=>n+data.workers[name].jobs,0),totalScored=workerNames.reduce((n,name)=>n+data.workers[name].scored,0),totalFirstPass=workerNames.reduce((n,name)=>n+data.workers[name].first_try,0),totalFixRounds=workerNames.reduce((n,name)=>n+data.workers[name].fix_rounds,0);
    const scoreRows=workerNames.map(name=>{const w=data.workers[name];return [name,w.scored?`${w.scored} of ${w.jobs} jobs`:'No scored jobs recorded',w.scored?`${w.avg_first_score.toFixed(2)} / 5`:'Not scored',w.scored?`${w.avg_final_score.toFixed(2)} / 5`:'Not scored',w.scored?`${w.avg_final_score>=w.avg_first_score?'+':''}${(w.avg_final_score-w.avg_first_score).toFixed(2)}`:'—'];});
    const scoreBars=workerNames.map(name=>{const w=data.workers[name];if(!w.scored)return `<article class="score-row"><div><b>${esc(name)}</b><small>No scored jobs recorded</small></div><div class="score-pair"><span class="score-unrated">NOT SCORED</span></div></article>`;return `<article class="score-row"><div><b>${esc(name)}</b><small>${w.scored} scored · ${w.jobs} credited jobs</small></div><div class="score-pair"><span><small>FIRST</small><i><em style="width:${w.avg_first_score/5*100}%"></em></i><b>${w.avg_first_score.toFixed(2)}</b></span><span><small>FINAL</small><i><em class="score-final" style="width:${w.avg_final_score/5*100}%"></em></i><b>${w.avg_final_score.toFixed(2)}</b></span></div></article>`;}).join('');
    function factoryPanel(team){const rows=data.jobs.filter(j=>j.team===team),branch=team==='G'?'factory/gameplay-v1':'factory/v1-wtt5ye';const phases=new Map(),types=new Map();for(const j of rows){const phase=j.metadata.phase||'Not recorded';const type=j.metadata.type||'Not recorded';phases.set(phase,(phases.get(phase)||0)+1);types.set(type,(types.get(type)||0)+1);}const bars=(map,cls)=>[...map.entries()].sort((a,b)=>a[0].localeCompare(b[0])).map(([label,n])=>`<div class="stat-bar-row"><div><span>${esc(label)}</span><b>${n} / ${rows.length}</b></div><i><em class="${cls}" style="width:${n/rows.length*100}%"></em></i></div>`).join('');return `<article class="factory-stat-card"><p class="eyebrow">TEAM ${team} / PINNED AUTHOR DATE ${esc(data.snapshotDates[branch])} UTC</p><h3>${rows.length} status-file dossiers</h3><p class="factory-population">Bar length = share of all ${rows.length} dossiers. Missing board fields stay visible.</p><div class="factory-breakdown"><div><h4>Board phase field</h4>${bars(phases,'phase-fill')}<small>Labels are preserved as recorded, including “Not recorded” and status-like values.</small></div><div><h4>Board type field</h4>${bars(types,'type-fill')}<small>The phase and type counts are separate cuts of the same job records.</small></div></div><a href="#jobs?team=${team}" class="book-button">Open Team ${team} dossiers →</a></article>`;}
    const dated=data.history.map(c=>({date:c.date,sha:c.sha,url:c.url})).sort((a,b)=>a.date.localeCompare(b.date));
    const firstDate=dated[0]?.date,lastDate=dated.at(-1)?.date;
    const toDay=iso=>new Date(`${iso}T12:00:00Z`);
    const first=toDay(firstDate),last=toDay(lastDate);
    const monday=d=>{const x=new Date(d);x.setUTCDate(x.getUTCDate()-((x.getUTCDay()+6)%7));x.setUTCHours(0,0,0,0);return x;};
    const start=monday(first),end=monday(last),weekCounts=new Map();
    for(const c of dated){const key=monday(toDay(c.date)).toISOString().slice(0,10);weekCounts.set(key,(weekCounts.get(key)||0)+1);}
    const weeks=[];for(let d=new Date(start);d<=end;d.setUTCDate(d.getUTCDate()+7)){const mondayISO=d.toISOString().slice(0,10),sun=new Date(d);sun.setUTCDate(sun.getUTCDate()+6);const sundayISO=sun.toISOString().slice(0,10),n=weekCounts.get(mondayISO)||0;weeks.push({start:mondayISO,end:sundayISO,n,partial:mondayISO<firstDate||sundayISO>lastDate});}
    const maxWeek=Math.max(...weeks.map(w=>w.n),1);
    const weekBars=weeks.map(w=>`<div class="week-column" title="${w.start} to ${w.end}: ${w.n} commits${w.partial?' · partial source window':''}"><b>${w.n}</b><i><em style="height:${w.n/maxWeek*100}%"></em></i><span>${esc(w.start.slice(5))}</span>${w.partial?'<small>partial</small>':''}</div>`).join('');
    const weekRows=weeks.map(w=>[w.start,`${w.start} — ${w.end}`,w.n,w.partial?'Partial source window':'Full calendar week']);
    const areas=Array.from({length:11},(_,i)=>String(i+1).padStart(2,'0'));
    const areaCounts=areas.map(area=>{const f=data.olympiad.findings.filter(x=>x.area===area);return [area,data.olympiad.runs.filter(x=>x.area===area).length,f.length,f.filter(x=>x.severity==='S1').length,f.filter(x=>x.severity==='S2').length,f.filter(x=>x.severity==='S3').length];});
    const checkCounts=data.olympiad.checks.reduce((a,c)=>(a[c.result||'Not recorded']=(a[c.result||'Not recorded']||0)+1,a),{});
    const statusCounts=data.olympiad.findings.reduce((a,f)=>(a[f.status||'Not recorded']=(a[f.status||'Not recorded']||0)+1,a),{});
    const evidenceRows=data.parts.map(p=>{const chapters=data.chapters.filter(c=>c.part===p.id);return [p.title,chapters.length,fmt(chapters.reduce((n,c)=>n+c.words,0)),new Set(chapters.flatMap(c=>c.sources.map(s=>s.url))).size];});
    const volumeLinks=data.parts.map((p,i)=>`<a href="#volume/${esc(p.id)}">${String(i+1).padStart(2,'0')} · ${esc(p.title)} →</a>`).join('');
    const links=olympiadLinks();
    const sections = [`<section class="atlas-section expanded-stat-section" id="stats-worker-mix" tabindex="-1"><p class="eyebrow">01 / WORKER ASSIGNMENTS · SCORECARD RECORDED 4 OCTOBER 2026</p><h2>Task mix and first-pass outcomes.</h2><p class="book-intro">The detailed matrix shows first-pass results inside each worker’s recorded task kind. Each cell means first passes / credited jobs, followed by the percentage. “No recorded jobs” is an absent assignment, not a zero pass rate. Phone work, build work and review work are different assignments.</p>${taskChart}<details class="matrix-detail"><summary>Inspect the full worker × task matrix</summary>${mixTable}</details><div class="stat-callout"><strong>${fmt(totalJobs)} credited jobs across ${workerNames.length} recorded worker cohorts</strong><span>The cohort tables record ${fmt(totalFirstPass)} first passes and ${fmt(totalFixRounds)} fix rounds across these task assignments. The board ledger records a separate 238-job first package; that is a different snapshot and denominator.</span></div>${external(research.visualScorecard.source,'Pinned scorecard and scope notes')}</section>`,
      `<section class="atlas-section expanded-stat-section" id="stats-review" tabindex="-1"><p class="eyebrow">02 / SCORED COHORTS · SCORECARD RECORDED 4 OCTOBER 2026</p><h2>First review and final review.</h2><p class="book-intro">Each pair compares the scorecard’s average first review with its average final review, on a five-point scale. The final average is the recorded review endpoint. Jobs are attributed to the original worker even when another worker performed a rescue; this comparison cannot establish who caused a score change.</p><div class="score-legend"><span><i class="score-key-first"></i>First scored review</span><span><i class="score-key-final"></i>Final scored review</span></div><div class="score-list">${scoreBars}</div>${table(['Worker cohort','Scored jobs / credited','First average','Final average','Difference'],scoreRows)}<p class="book-scope">Only ${fmt(totalScored)} of the ${fmt(totalJobs)} credited jobs received numeric scores. The cohort sizes differ, task assignments are unequal, and Claude reviewed some of its own work. These are recorded review outcomes, not a controlled model benchmark.</p>${external(research.visualScorecard.source,'Score definitions, denominators and reviewer caveats')}</section>`,
      `<section class="atlas-section expanded-stat-section" id="stats-factories" tabindex="-1"><p class="eyebrow">03 / FACTORY COMPOSITION · PINNED TEAM G AND V SNAPSHOTS</p><h2>What the factory records contain.</h2><p class="book-intro">Each panel counts board metadata attached to all status-file dossiers in its pinned snapshot, including dossiers whose job number is absent from the board. The views keep “phase” and “type” separate and retain missing or unusual labels.</p><div class="factory-stat-grid">${factoryPanel('G')}${factoryPanel('V')}</div><p class="book-scope">These fields describe the work tracked by each factory. They are not completion rates or production-feature counts; inspect each job’s recorded status separately.</p>${external(source('factory/gameplay-v1','project-documents/gameplay-factory/BOARD.json'),'Team G board')}${external(source('factory/v1-wtt5ye','project-documents/factory/BOARD.json'),'Team V board')}</section>`,
      `<section class="atlas-section expanded-stat-section" id="stats-weeks" tabindex="-1"><p class="eyebrow">04 / INTEGRATION RHYTHM · PINNED MAIN THROUGH ${esc(lastDate)}</p><h2>Main integration, week by week.</h2><p class="book-intro">This view groups ${fmt(dated.length)} first-parent commits by UTC calendar week. Author timestamps are converted to UTC before grouping. Bars count commits on the integration spine; they do not measure features, labor, quality or branch activity.</p><div class="week-chart" role="img" tabindex="0" aria-label="Weekly first-parent main commits. Values and exact date ranges are listed in the table below.">${weekBars}</div>${table(['Week starts Monday UTC','Calendar window','First-parent commits','Window in snapshot'],weekRows)}<p class="book-scope">The first and last weeks are partial because the pinned history begins ${esc(firstDate)} and ends ${esc(lastDate)}. Other weeks show complete Monday-through-Sunday calendar intervals.</p>${external(`${repo}/commits/${data.refs.main}`,'Open the pinned main history')}</section>`,
      `<section class="atlas-section expanded-stat-section" id="stats-olympiad" tabindex="-1"><p class="eyebrow">05 / BUG OLYMPIAD · ARCHIVED BOARD INPUTS</p><h2>Olympiad runs and finding files.</h2><p class="book-intro">This census separates run records from finding files. Severity describes each finding file’s recorded label; a later check can challenge the claim.</p>${table(['Area','Run records','Finding files','S1 labels','S2 labels','S3 labels'],areaCounts)}<div class="atlas-two"><article class="atlas-box"><h3>${data.olympiad.runs.length} run records</h3><p>Runs were recorded across all eleven numbered areas. Counts are archived attempts, not unique defects found.</p></article><article class="atlas-box"><h3>${data.olympiad.findings.length} finding files</h3>${stateChips(statusCounts)}<p>File labels can repeat an identifier and should not be read as unique confirmed bugs.</p></article></div><h3 class="stat-subhead">Check records, counted separately</h3>${table(['Recorded check result','Check records'],Object.entries(checkCounts).sort((a,b)=>a[0].localeCompare(b[0])).map(([k,v])=>[k,v]))}<p class="book-scope">The ${data.olympiad.checks.length} check records are counted from their own files, independently of runs and findings. The hunt explorer assigns a check only for a one-to-one identifier match. The linkage audit below keeps ambiguous and unmatched records visible.</p>${external(data.olympiad.source.url,'Open the pinned GOALS archive')}</section>`,
      `<section class="atlas-section expanded-stat-section" id="stats-evidence" tabindex="-1"><p class="eyebrow">06 / THE CHRONICLE’S EVIDENCE MAP · EDITION 03</p><h2>The book, volume by volume.</h2><p class="book-intro">Chapter counts, chapter-text word counts and distinct cited source URLs describe the evidence attached to each volume.</p>${table(['Volume','Chapters','Words','Distinct source URLs in this volume'],evidenceRows)}<div class="volume-source-links">${volumeLinks}</div><p class="book-scope">A pinned source can support chapters in several volumes. Volume-level unique counts overlap; adding them does not equal the book-wide unique-source index. The word count includes chapter titles, decks, paragraphs, subheadings, lists and table text. It excludes the separate job, release and commit archives.</p><p class="book-scope">Book-wide: ${data.chapters.length} chapters · ${fmt(data.wordCount)} words · ${data.sources.length} indexed pinned source files.</p></section>`,

      `<section class="atlas-section expanded-stat-section" id="stats-lineage" tabindex="-1"><p class="eyebrow">07 / BOARD MEMBERSHIP · PINNED TEAM G AND V SNAPSHOTS</p><h2>Why the factory totals differ.</h2><p class="book-intro">Board definitions and status files are different inventories. This comparison joins them only by the normalized job number within the same team and pinned branch.</p>${table(['Team','Board definitions','Status dossiers','Status files matched to board','Status files absent from board','Board entries without status file'],['G','V'].map(team=>{const c=data.factoryCensus[team];return [team,c.boardEntries,data.jobs.filter(j=>j.team===team).length,c.matchedStatusFiles,c.unmatchedStatusNumbers.length,c.boardWithoutStatus.length];}))}<div class="method-grid">${['G','V'].map(team=>{const c=data.factoryCensus[team];return `<article><h3>Team ${team}: retain the unmatched records</h3><p>Status-file numbers absent from BOARD.json: ${esc(c.unmatchedStatusNumbers.join(', ')||'None')}.</p><p>Board numbers without a status file in the studied corpus: ${esc(c.boardWithoutStatus.join(', ')||'None')}.</p>${external(c.source.url,'Pinned board definitions')}</article>`;}).join('')}</div><p class="book-scope">The factory composition view counts all status-file dossiers, so unmatched records contribute to “Not recorded” for board fields. Absence from one inventory does not establish missing work or a failed job. The historical 237-job worker scorecard has its own inclusion rules and predates these inventories.</p></section>`,
      `<section class="atlas-section expanded-stat-section" id="stats-linkage" tabindex="-1"><p class="eyebrow">08 / QA RECORD LINKAGE · ARCHIVED GOALS INPUTS</p><h2>Can the QA records be joined?</h2><p class="book-intro">A matching identifier is usable only when it identifies one finding file and one check file. Duplicate finding IDs are kept as separate files and are not silently assigned the same verdict.</p><div class="book-counts"><div><strong>${links.findings.size}</strong><span>DISTINCT FINDING IDS</span></div><div><strong>${links.rows.filter(f=>f.check).length}</strong><span>ONE-TO-ONE CHECK LINKS</span></div><div><strong>${links.rows.filter(f=>f.linkState==='ambiguous').length}</strong><span>FILES WITH AMBIGUOUS IDS</span></div><div><strong>${links.orphanChecks.length}</strong><span>CHECKS WITHOUT FINDING FILES</span></div></div>${table(['Inventory or relationship','Count','Counting rule'],[['Finding files',data.olympiad.findings.length,'Every archived finding-file record'],['Distinct finding identifiers',links.findings.size,'Distinct recorded ID strings'],['Identifiers used by multiple finding files',[...links.findings.values()].filter(a=>a.length>1).length,'IDs with more than one finding record'],['Finding files with one-to-one check link',links.rows.filter(f=>f.check).length,'Exactly one finding and exactly one check for the ID'],['Finding files with ambiguous identifier',links.rows.filter(f=>f.linkState==='ambiguous').length,'Duplicate finding or multiple candidate checks'],['Finding files without a check link',links.rows.filter(f=>f.linkState==='unreviewed').length,'Unique finding ID with no matching check'],['Check records with no finding ID in archive',links.orphanChecks.length,'Check ID absent from finding inventory']])}<h3 class="stat-subhead">Ambiguous finding records</h3>${table(['Identifier','Finding record path','Candidate check records'],links.rows.filter(f=>f.linkState==='ambiguous').map(f=>[f.id,f.recordPath,f.candidates.length]))}<h3 class="stat-subhead">Check records with no matching finding</h3>${table(['Identifier','Recorded result','Check record path'],links.orphanChecks.map(c=>[c.id,c.result,c.recordPath]))}<p class="book-scope">One-to-one linkage is an identifier check, not independent verification of the reviewer’s conclusion. Checks can target a different main SHA from the original claim. Read each record’s source, evidence and tested revision before interpreting the result.</p>${external(data.olympiad.source.url,'Inspect the pinned archive') }<a class="book-button" href="#atlas">Open the filtered hunt explorer →</a></section>`
    ];
    return (selected?`<details class="view-switcher"><summary>Explore another statistical view</summary>${statsNav(selected)}</details>`:statsNav())+sections.filter(s=>!selected||s.includes(`id="${selected}"`)).join('');
  }
  function atlas(){
    activeChapter=null;const totals=research.repository;
    main.innerHTML=heading('THE RESEARCH ATLAS / COMPARE, TRACE, INSPECT','The system,<br><span>made visible.</span>','Explore the measured worker cohorts, the factory snapshots, the Olympiad archive and the proof architecture. Every panel defines what its numbers mean.')+`<div class="book-counts"><div><strong>${fmt(totals.reachableCommits)}</strong><span>REACHABLE COMMIT OBJECTS</span></div><div><strong>${totals.contractPaths}</strong><span>REGISTERED TEST PATHS</span></div><div><strong>${totals.heavyProofIds}</strong><span>HEAVY PROOF IDENTIFIERS</span></div><div><strong>${totals.mappedSteps}</strong><span>GATE COVERAGE MAPPINGS</span></div></div>${expandedStats()}<section class="atlas-section"><p class="eyebrow">MODEL COHORT / RECORDED 4 OCTOBER</p><h2>Performance depends on the work.</h2><p class="book-intro">Choose a job kind to see the observed first-pass counts. Smaller pieces, different assignments and different review conditions affect this comparison.</p><div class="atlas-control"><label for="worker-kind">JOB KIND</label><select id="worker-kind"><option value="All">All recorded work</option>${[...new Set(Object.values(data.workers).flatMap(w=>Object.keys(w.by_kind)))].map(k=>`<option value="${esc(k)}">${esc(k)}</option>`).join('')}</select></div><div id="worker-comparison"></div><div class="book-callout"><strong>READ THE DENOMINATOR</strong><p>The cohort contains 237 jobs, 215 first passes, 29 fix rounds and 76 scored jobs. Assignments were unequal, and Claude reviewed Claude’s own work. These observations describe this factory’s routing history; they are not a controlled general model benchmark.</p></div>${external(research.visualScorecard.source,'Read the complete historical scorecard')}</section><section class="atlas-section"><p class="eyebrow">THE TWO FACTORIES / PINNED STATUS SNAPSHOTS</p><h2>Different work. Different acceptance records.</h2><div class="atlas-two">${['v','g'].map(k=>{const f=research.factories[k];return `<div class="atlas-box"><span class="eyebrow">TEAM ${k.toUpperCase()}</span><h3>${f.jobs.length} status files</h3>${stateChips(f.states)}<p>${k==='v'?`${f.intakePass} records retain a Claude intake PASS marker.`:`${(f.states.DONE||0)+(f.states.MERGED||0)} records carry DONE or MERGED labels.`}</p><a class="book-button" href="#jobs">Inspect job dossiers →</a></div>`;}).join('')}</div>${scope('These current pinned file counts use different denominators from the older worker evaluation tables. They do not certify the deployed product.')}<h3>Gameplay worker record</h3>${table(['Job','Worker label','First time','Fix rounds','What review or checks caught'],research.gameplayScorecard.rows.map(r=>[r.job,r.worker,r.firstTime,r.fixRounds,r.caught]))}${external(research.gameplayScorecard.source,'Gameplay scorecard and backfill limits')}</section><section class="atlas-section"><p class="eyebrow">BUG OLYMPIAD / ARCHIVED BOARD INPUTS</p><h2>A finding is a claim to investigate.</h2><div class="atlas-two"><div class="atlas-box"><h3>${data.olympiad.runs.length} run records</h3>${stateChips(data.olympiad.runs.reduce((a,r)=>(a[r.mode||'unknown']=(a[r.mode||'unknown']||0)+1,a),{}))}<p>The archive covers all eleven numbered areas. Run records include partial and blocked attempts.</p></div><div class="atlas-box"><h3>${data.olympiad.findings.length} finding files · ${data.olympiad.checks.length} check records</h3>${stateChips(data.olympiad.checks.reduce((a,r)=>(a[r.result||'unknown']=(a[r.result||'unknown']||0)+1,a),{}))}<p>Later checks can disprove a claim. File counts include duplicate IDs and are not a count of unique confirmed bugs.</p></div></div><div class="atlas-control"><label for="hunt-area">AREA</label><select id="hunt-area"><option value="All">All areas</option>${Array.from({length:11},(_,i)=>`<option value="${String(i+1).padStart(2,'0')}">${String(i+1).padStart(2,'0')}</option>`).join('')}</select><label for="hunt-state">CHECK STATUS</label><select id="hunt-state"><option value="All">All records</option><option value="real">Recorded: real</option><option value="not_real">Recorded: not real</option><option value="unreviewed">No linked check</option><option value="ambiguous">Ambiguous identifier</option></select></div><div id="hunt-records"></div><details class="acceptance-domain"><summary><strong>53</strong><span>INSPECT THE RUN RECORDS</span><span aria-hidden="true">+</span></summary><p class="book-scope">The area filter above also filters these runs. Coverage and clean-confidence percentages are the worker’s recorded estimates; they are not measured probabilities or comparable model benchmark scores.</p><div id="hunt-runs"></div></details>${scope(data.olympiad.scope)}${external(data.olympiad.source.url,'Open the copied Olympiad archive')}</section><section class="atlas-section"><p class="eyebrow">THE INHERITED IMPACT GRAPH</p><h2>A change carries downstream obligations.</h2><div class="atlas-control"><label for="invariant-select">STARTING INVARIANT</label><select id="invariant-select">${data.invariants.map(i=>`<option value="${i.id}">${esc(i.id.replaceAll('_',' '))}</option>`).join('')}</select></div><div class="invariant-cards" id="invariant-map"></div>${scope('This panel follows the graph’s named consumer edges. Selecting Identity Cloud Foundation also reaches Pairing Rivalry, Remote Joining and Shared Setup. The graph’s minimum route survives POS20; registered definitions are not a report of a fresh passing execution.')}</section><section class="atlas-section"><p class="eyebrow">SSJR-2.1 / CAPABILITY WEIGHTS</p><h2>One hundred points.<br>Three layers of evidence.</h2><p class="book-intro">These are the frozen model’s weights. The pinned acceptance ledger still records zero credit. Open a domain to see its capabilities and dependencies.</p><div class="acceptance-grid">${data.acceptance.map(d=>`<details class="acceptance-domain"><summary><strong>${d.weight}</strong><span>${esc(d.id.replaceAll('-',' ').toUpperCase())}</span><span aria-hidden="true">+</span></summary><ul>${d.capabilities.map(c=>`<li><b>${c.weight} points · ${esc(c.id)}</b><br>${esc(c.outcome)}<br><small>Depends on: ${esc(c.dependsOn.join(', ')||'No prior capability')}</small></li>`).join('')}</ul></details>`).join('')}</div>${scope('Credit requires automated evidence on the credited production authority, a validated physical two-device journey pair, and hash-bound owner attestation. The displayed weights are definitions, not earned scores. A valid longer run can cover multi-season capability; source, merge or deployment alone earns no credit.')}</section>`;
    function workers(){const kind=$('#worker-kind').value;const rows=Object.entries(data.workers).map(([name,w])=>{const a=kind==='All'?[w.jobs,w.first_try]:w.by_kind[kind];return a&&a[0]?{name,n:a[0],pass:a[1],w}:null;}).filter(Boolean);$('#worker-comparison').innerHTML=`<div class="worker-bars">${rows.map(r=>`<div class="worker-bar"><div class="bar-caption"><span>${esc(r.name)}</span><b>${r.pass} / ${r.n} · ${(r.pass/r.n*100).toFixed(1)}%</b></div><div class="bar-track"><span style="width:${(r.pass/r.n*100).toFixed(2)}%"></span></div><small>${kind==='All'?`${r.w.fix_rounds} recorded fix rounds · ${r.w.scored} scored jobs`:'First-pass observations for this kind only'}</small></div>`).join('')}</div>${table(['Worker label','Jobs','First passes','Rate','First / final score'],rows.map(r=>[r.name,r.n,r.pass,`${(r.pass/r.n*100).toFixed(1)}%`,kind==='All'&&r.w.scored?`${r.w.avg_first_score} / ${r.w.avg_final_score} (${r.w.scored} scored)`:'Not recorded for this slice']))}`;}
    function hunts(){const area=$('#hunt-area').value;const state=$('#hunt-state').value;const rows=olympiadLinks().rows.filter(f=>(area==='All'||f.area===area)&&(state==='All'||f.linkState===state));$('#hunt-records').innerHTML=table(['Area','Finding ID / recorded title','Severity','Initial label','Uniquely matched review result'],rows.map(f=>[f.area,`${f.id} · ${f.title}`,f.severity,f.status,f.linkLabel]))+rows.filter(f=>f.check).map(f=>`<details class="hunt-evidence"><summary>${esc(f.id)} · ${esc(f.check.result.replaceAll('_',' '))}</summary><p>${esc(f.check.evidenceExcerpt||'Read the archive for the complete evidence.')}</p><small>Short source excerpt · ${esc(f.check.recordPath)}<br>Claim main SHA: ${esc(f.main_sha||'Not recorded')}<br>Check main SHA: ${esc(f.check.main_sha||'Not recorded')}</small></details>`).join('');const runs=data.olympiad.runs.filter(r=>area==='All'||r.area===area);$('#hunt-runs').innerHTML=table(['Run record','Area / mode','Files listed read','Coverage estimate','Clean-confidence estimate','Finding references / partial'],runs.map(r=>[r.run||r.recordPath.split('/').pop(),`${r.area} / ${r.mode}`,r.filesRead,r.coverage_pct==null?'Not recorded':`${r.coverage_pct}%`,r.clean_confidence_pct==null?'Not recorded':`${r.clean_confidence_pct}%`,`${(r.findings||[]).length} / ${r.partial==null?'Not recorded':r.partial?'Partial':'Not marked partial'}`]));}
    function graph(){const chosen=$('#invariant-select').value;const seen=new Set();function visit(id){if(seen.has(id))return;seen.add(id);data.invariants.find(i=>i.id===id)?.consumers.forEach(visit);}visit(chosen);$('#invariant-map').innerHTML=data.invariants.map(i=>`<article class="invariant-card" style="${seen.has(i.id)?'border-color:var(--gold)':''}"><strong>${esc(i.id.replaceAll('_',' '))}</strong><p>${seen.has(i.id)?'SELECTED IN CLOSURE · ':''}${i.testIndexes.length} manifest indexes<br>Consumers: ${esc(i.consumers.map(c=>c.replaceAll('_',' ')).join(' → ')||'No named consumer')}<br>Proof bundles: ${esc(i.proofBundles.join(', ')||'None assigned here')}</p></article>`).join('');}
    $('#worker-kind').addEventListener('change',workers);$('#hunt-area').addEventListener('change',hunts);$('#hunt-state').addEventListener('change',hunts);$('#invariant-select').addEventListener('change',graph);workers();hunts();graph();markNav('atlas');
  }
  function sources(){
    activeChapter=null;let page=0;const size=20;main.innerHTML=heading('PINNED SOURCES / FOLLOW EVERY CLAIM','The evidence<br><span>has an address.</span>','Search the source files behind the book, job dossiers and release collection. Each link points to the studied commit rather than a moving branch.')+`<div class="archive-controls"><div class="wide-control"><label for="source-query">SEARCH FILE NAMES, PATHS OR LABELS</label><input id="source-query" type="search" placeholder="e.g. quality, Candidate C, JOB-1010"></div><div><label for="source-branch">BRANCH SNAPSHOT</label><select id="source-branch"><option value="All">All snapshots</option>${[...new Set(data.sources.map(s=>s.branch))].map(r=>`<option>${esc(r)}</option>`).join('')}</select></div></div><p class="book-scope" id="source-count" role="status"></p><div id="source-rows"></div><div class="archive-pagination"><button class="book-button" id="source-prev">← Previous</button><span id="source-page"></span><button class="book-button" id="source-next">Next →</button></div>${scope('The research corpus is larger than this index. The index counts distinct source URLs actually attached to the published book and archives. Editorial conclusions are explanations of those records, not an independent execution of every project check.')}`;
    function render(){const q=$('#source-query').value.toLowerCase().trim();const rows=data.sources.filter(s=>($('#source-branch').value==='All'||s.branch===$('#source-branch').value)&&`${s.path} ${s.label}`.toLowerCase().includes(q));const pages=Math.max(1,Math.ceil(rows.length/size));page=Math.min(page,pages-1);$('#source-count').textContent=`${rows.length} matching pinned files`;$('#source-rows').innerHTML=sourceNotes(rows.slice(page*size,(page+1)*size))||'<div class="book-empty">No source matches.</div>';$('#source-page').textContent=`${page+1} / ${pages}`;$('#source-prev').disabled=page===0;$('#source-next').disabled=page===pages-1;}
    $('#source-query').addEventListener('input',()=>{page=0;render();});$('#source-branch').addEventListener('change',()=>{page=0;render();});$('#source-prev').addEventListener('click',()=>{page--;render();});$('#source-next').addEventListener('click',()=>{page++;render();});render();markNav('sources');
  }
  function search(q=''){
    activeChapter=null;main.innerHTML=heading('FULL-TEXT DISCOVERY','Find the detail<br><span>you came for.</span>','Search across chapter prose, job dossiers and release records. Commit history has its own complete search.')+`<div class="archive-controls"><div class="wide-control"><label for="full-query">SEARCH THE BOOK</label><input id="full-query" type="search" placeholder="e.g. Fable, scoring, rollback, Physio" value="${esc(q)}"></div><div><label for="full-kind">COLLECTION</label><select id="full-kind"><option value="All">All collections</option><option value="chapter">Chapters</option><option value="job">Jobs</option><option value="release">Releases</option><option value="latest">Latest update</option></select></div></div><p class="book-scope" id="full-count" role="status"></p><div class="search-results" id="full-results"></div>`;
    const index=[...data.chapters.map(c=>({kind:'chapter',title:c.title,dek:c.dek,text:JSON.stringify(c.blocks),url:`#read/${c.id}`,label:`CHAPTER ${pad(c.number)} / ${part(c.part).title}`})),...data.jobs.map(j=>({kind:'job',title:j.title,dek:`Team ${j.team} · ${j.rawState} · ${j.worker}`,text:`${j.number} ${j.briefExcerpt} ${j.statusExcerpt}`,url:`#job/${j.id}`,label:`TEAM ${j.team} / JOB ${j.number}`})),...data.releases.map(r=>({kind:'release',title:r.title,dek:`${r.runtime} · ${r.date} last source commit`,text:r.sections.join(' '),url:`#release/${r.id}`,label:'RELEASE RECORD'}))];
    index.push(...(window.chronicleCurrentSearch||[]),...(window.chronicleLatestSearch||[]));
    function render(){const terms=$('#full-query').value.toLowerCase().trim().split(/\s+/).filter(Boolean);const kind=$('#full-kind').value;const rows=terms.length?index.filter(r=>(kind==='All'||r.kind===kind)&&terms.every(t=>`${r.title} ${r.dek} ${r.text}`.toLowerCase().includes(t))):[];$('#full-count').textContent=terms.length?`${rows.length} results · first ${Math.min(rows.length,80)} shown`:'Type a subject, job number, model or system name.';$('#full-results').innerHTML=rows.slice(0,80).map(r=>`<a class="search-result" href="${esc(r.url)}"><span class="eyebrow">${esc(r.label)}</span><strong>${esc(r.title)}</strong><p>${esc(r.dek)}</p></a>`).join('')||(terms.length?'<div class="book-empty">No results. Try a shorter query or another collection.</div>':'');}
    $('#full-query').addEventListener('input',render);$('#full-kind').addEventListener('change',render);render();markNav('search');
  }
  function savedChapters(){activeChapter=null;main.innerHTML=heading('YOUR LOCAL READING LIST','Keep a chapter<br><span>close by.</span>','Saved chapters and your most recent page stay in this browser. They do not change the project repository.')+`<div class="chapter-shelf">${data.chapters.filter(c=>saved.has(c.id)).map(chapterEntry).join('')||'<div class="book-empty">Open a chapter and choose Save chapter to add it here.</div>'}</div>`;markNav('saved');}
  function notFound(){activeChapter=null;main.innerHTML=heading('PAGE NOT FOUND','Return to<br><span>the Chronicle.</span>')+'<a class="book-button gold" href="#contents">Open contents →</a>';}
  function route(){
    const raw=location.hash.slice(1)||'contents';const [path,query='']=raw.split('?');const [kind,...idParts]=path.split('/');const id=idParts.join('/');document.title='The Complete Chronicle — Career Mode Showdown';closeDrawer();
    if(kind==='latest'){activeChapter=null;const html=window.renderChronicleCurrent?.(id);if(html){main.innerHTML=html;window.bindChronicleCurrent?.(id);markNav('latest');}else notFound();}else if(kind==='edition08'){activeChapter=null;main.innerHTML=window.renderChronicleEdition08?.(id)||'';markNav('latest');}else if(kind==='edition07'){activeChapter=null;const html=window.renderChronicleArchive?.(id);if(html){main.innerHTML='<aside class="historical-snapshot">Archived 12 October checkpoint. <a href="#latest">Read the 17 October update →</a></aside>'+html;window.bindChronicleArchive?.(id);markNav('latest');}else notFound();}else if(kind==='edition05'){activeChapter=null;const html=window.renderChronicleLatest?.(id);if(html){main.innerHTML=html;markNav('latest');}else notFound();}else if(kind==='read')readChapter(id);else if(kind==='volume')contents(id);else if(kind==='contents')contents();else if(kind==='atlas')atlas();else if(kind==='numbers')numbers();else if(kind==='jobs'||kind==='releases')archive(kind,new URLSearchParams(query).get('team')||'All');else if(kind==='job'||kind==='release')record(kind,id);else if(kind==='timeline')timeline();else if(kind==='sources')sources();else if(kind==='saved')savedChapters();else if(kind==='search')search(new URLSearchParams(query).get('q')||'');else if(kind.startsWith('stats-'))statistics(kind);else notFound();
    if(['atlas','numbers','jobs','releases','timeline'].includes(kind)||(kind.startsWith('stats-')&&kind!=='stats-evidence'))main.insertAdjacentHTML('afterbegin','<aside class="historical-snapshot">Historical source snapshots through 7 October 2026. <a href="#latest">Read the 17 October picture and current counts →</a></aside>');
    if(kind.startsWith('stats-')){const target=document.getElementById(kind);target?.focus({preventScroll:true});target?.scrollIntoView({block:'start'});return;}
    window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});
  }
  $('#volume-nav').innerHTML=data.parts.map((p,i)=>`<a data-part="${esc(p.id)}" href="#volume/${esc(p.id)}"><span>${String(i+1).padStart(2,'0')}</span>${esc(p.title)}</a>`).join('');
  const theme=storage.get('theme','dark');document.body.dataset.theme=theme;
  function themeLabel(){$('#theme-toggle').setAttribute('aria-label',document.body.dataset.theme==='dark'?'Use light reading theme':'Use dark reading theme');}themeLabel();
  $('#theme-toggle').addEventListener('click',()=>{document.body.dataset.theme=document.body.dataset.theme==='dark'?'light':'dark';storage.set('theme',document.body.dataset.theme);themeLabel();});
  $('#menu-toggle').addEventListener('click',()=>{const open=!document.body.classList.contains('drawer-open');document.body.classList.toggle('drawer-open',open);$('#menu-toggle').setAttribute('aria-expanded',String(open));$('#drawer-backdrop').hidden=!open;});$('#drawer-backdrop').addEventListener('click',closeDrawer);
  $('#book-search-form').addEventListener('submit',e=>{e.preventDefault();location.hash=`search?q=${encodeURIComponent($('#book-search').value.trim())}`;});
  document.addEventListener('click',async e=>{if(e.target.closest('.skip')){e.preventDefault();main.focus({preventScroll:true});return;}const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;
    if(action==='save'&&activeChapter){const id=activeChapter.id;saved.has(id)?saved.delete(id):saved.add(id);storage.set('saved',[...saved]);button.setAttribute('aria-pressed',String(saved.has(id)));button.textContent=saved.has(id)?'♥ Saved':'♡ Save chapter';readingState();}
    if(action==='copy'){try{await navigator.clipboard.writeText(location.href);toast('Chapter link copied');}catch{toast('Use the address bar to copy this chapter link');}}
    if(action==='print')window.print();
    if(action==='print-all'){$('#print-book').innerHTML=`<section class="print-cover"><p>CAREER MODE SHOWDOWN / RESEARCH EDITION 11</p><h1>The Complete<br>Chronicle.</h1><p>${data.chapters.length} editorial chapters · ${fmt(data.wordCount)} words<br>Dated historical sources plus the 1 November 2026 staging update</p><p>${esc(data.method)}</p></section>`+data.chapters.map(c=>`<article class="print-chapter"><p class="eyebrow">CHAPTER ${pad(c.number)} / ${esc(part(c.part).title)}</p><h1>${esc(c.title)}</h1><p>${esc(c.dek)}</p><div class="chapter-prose">${blocks(c)}</div><div class="print-ref">${c.sources.map(s=>`${esc(s.label)}: ${esc(s.url)}`).join('<br>')}</div></article>`).join('');document.body.classList.add('print-all');window.print();}
  });
  window.addEventListener('afterprint',()=>{document.body.classList.remove('print-all');$('#print-book').innerHTML='';});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer();if(e.target.closest('input,textarea,select,button')||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='/'){e.preventDefault();if(window.innerWidth>620)$('#book-search').focus();else location.hash='search';}if(activeChapter&&['[',']'].includes(e.key)){const i=data.chapters.indexOf(activeChapter)+(e.key===']'?1:-1);if(data.chapters[i])location.hash=`read/${data.chapters[i].id}`;}});
  window.addEventListener('hashchange',route);route();
  window.ChronicleBook={filteredJobs,chapter,route,olympiadLinks,statDefinitions,wordCount:data.wordCount};
})();
